"      // Total counters (Only count normal, active, non-free successful sales)
      const isCancelled = o.status === 'CANCELLED';
      const isDeleted = o.status === 'DELETED';
      const isFree = o.status === 'FREE' || 
                     String(o.payment_method || '').toUpperCase() === 'FREE' || 
                     String(o.payment_method || '').toUpperCase() === 'COMPLIMENTARY';
      const isNormalSale = !isCancelled && !isDeleted && !isFree;

      if (isNormalSale) {
        acc.totalSales += amt;
        acc.totalCount += 1;

        const dateVal = o.created_at || o.timestamp || o.date;
        if (dateVal) {
          const orderDate = new Date(dateVal);
          const isToday = orderDate.getFullYear() === now.getFullYear() &&
                          orderDate.getMonth() === now.getMonth() &&
                          orderDate.getDate() === now.getDate();
          const isThisMonth = orderDate.getFullYear() === now.getFullYear() &&
                              orderDate.getMonth() === now.getMonth();

          if (isToday) {
            acc.todaySales += amt;
            acc.todayCount += 1;
          }
          if (isThisMonth) {
            acc.monthSales += amt;
            acc.monthCount += 1;
          }
        }
      }"

